      "rank": 1,
      "ballot_id": "B015",
      "proposed_laureates": [
        "Francis Halzen",
        "Albrecht Karle"
      ],
      "assessment": {
        "nobel_worthiness": "The opening of high-energy neutrino astronomy is a decisive new observational window on the Universe and required an exceptional experimental enterprise.",
        "attribution": "Halzen and Karle are strong representatives of the conception, construction, and scientific realization of IceCube, although the collaboration was necessarily broad.",
        "maturity": "Astrophysical neutrinos have been established over more than a decade, with a sustained instrument and a mature scientific field.",
        "uncertainties": [
          "The appropriate individual attribution within a very large collaboration requires careful historical review."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B009",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have transformed precision timekeeping and enable unusually powerful tests and measurements across physics.",
        "attribution": "Katori originated the magic-wavelength lattice-clock concept, while Ye made decisive experimental advances and established the platform's reach.",
        "maturity": "Independent laboratories have achieved extraordinary, reproducible performance and the technology is clearly mature.",
        "uncertainties": [
          "A historical review should distinguish the central lattice-clock innovation from the wider development of optical frequency metrology."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B038",
      "proposed_laureates": [
        "Enrico Costa",
        "Filippo Frontera",
        "Shrinivas R. Kulkarni"
      ],
      "assessment": {
        "nobel_worthiness": "Afterglow localization converted gamma-ray bursts from enigmatic transients into cosmological probes and established a major field of high-energy astrophysics.",
        "attribution": "Costa and Frontera represent the instrumental and observational breakthrough, while Kulkarni was pivotal in exploiting precise localizations across wavelengths.",
        "maturity": "The cosmological origin and broad physical significance of gamma-ray bursts are firmly established after decades of follow-up.",
        "uncertainties": [
          "The relative roles of satellite teams and the many follow-up observers need detailed attribution assessment."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Masato Sagawa",
        "John J. Croat"
      ],
      "assessment": {
        "nobel_worthiness": "Neodymium-iron-boron magnets are an outstanding materials discovery with durable physical and technological consequences.",
        "attribution": "Sagawa and Croat are the central credited inventors of complementary routes to the high-performance NdFeB magnet.",
        "maturity": "The materials, their magnetic properties, and their importance in devices have been established for decades.",
        "uncertainties": [
          "The committee should examine whether the simultaneous industrial development has additional indispensable contributors."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B022",
      "proposed_laureates": [
        "Christian J. Bordé",
        "Mark A. Kasevich"
      ],
      "assessment": {
        "nobel_worthiness": "Atom interferometry created a versatile precision-measurement method with fundamental and practical reach.",
        "attribution": "Bordé supplied foundational concepts and Kasevich provided landmark realizations, though the development drew on a wider community.",
        "maturity": "The technique is well established in precision gravimetry, inertial sensing, and fundamental tests.",
        "uncertainties": [
          "Individual credit is difficult because several foundational interferometric methods developed in parallel."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Charles H. Bennett",
        "Gilles Brassard",
        "Artur Ekert"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum key distribution gave quantum information one of its clearest operational consequences: security based on physical principles.",
        "attribution": "Bennett and Brassard introduced the foundational protocol, while Ekert supplied a conceptually distinct entanglement-based formulation.",
        "maturity": "The underlying physics is secure and implementations are mature enough for extensive field deployment.",
        "uncertainties": [
          "The practical-security claims and the boundary between foundational protocols and later engineering deserve careful examination."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B040",
      "proposed_laureates": [
        "Alan H. Guth",
        "Andrei Linde",
        "Viatcheslav Mukhanov"
      ],
      "assessment": {
        "nobel_worthiness": "Inflation and the mechanism for primordial fluctuations profoundly changed cosmology and provide a compelling account of observed structure.",
        "attribution": "Guth, Linde, and Mukhanov represent distinct essential advances: the inflationary idea, viable inflationary dynamics, and the quantum origin of perturbations.",
        "maturity": "Inflation is a highly successful framework, with major observational support for its broad predictions.",
        "uncertainties": [
          "No uniquely diagnostic observational confirmation identifies a specific inflationary mechanism.",
          "The primordial gravitational-wave prediction remains unconfirmed."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Maura McLaughlin",
        "Michael Kramer",
        "Richard N. Manchester"
      ],
      "assessment": {
        "nobel_worthiness": "Pulsar timing arrays have opened the nanohertz gravitational-wave band, a major extension of gravitational-wave astronomy.",
        "attribution": "The credited researchers are important leaders, but the result rests on several international arrays and a long collective development of pulsar timing.",
        "maturity": "Independent array results provide strong evidence for a common nanohertz background, but source characterization is still developing.",
        "uncertainties": [
          "The astrophysical origin and detailed spectrum of the background remain under active investigation.",
          "Attribution across the multiple pulsar-timing collaborations is unusually diffuse."
        ]
      }
    }
  ]
}
